           // 40FB10Pのフルスペック
           const currentSpecs = {'画面サイズ': '55 V型(インチ)', '画素数': '3840x2160', 'パネル種類': 'None', 'HDR方式': 'HDR10HLG', '映像処理エンジン': 'None', 'バックライト': 'None', '量子ドット': 'None', '倍速機能': '倍速駆動', 'BS 8K': 'None', 'BS 4K/110度CS 4K': '1', '録画機能': '外付けHDD', 'ドライブ内蔵': 'None', '自動録画機能': 'None', '2番組同時録画': 'None', '早見再生': 'None', 'スマートスピーカー連携': 'Amazon Alexa', '回転式スタンド': 'None', 'HDMI端子': '4端子ARC対応', 'リモコン(音声操作)': 'None', 'スピーカー数': 'None', '幅x高さx奥行': '1226x754x272 mm', '重量': '22.7 kg'};



           // ====================================================================
